command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: GEISTERDIENER (Ohne rotes Banner beim Löschen)
// ==========================================

(async () => {
    // --- 1. SICHERHEITS-CHECK: FRAMEWORK LADEN ---
    if (typeof DSK === "undefined" || !globalThis.DSK) {
        const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
        if (fwMacro) await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150)); 
    }

    if (typeof DSK === "undefined" && !globalThis.DSK) {
        return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework konnte nicht geladen werden!");
    }
    const DSK_FW = globalThis.DSK || DSK; 

    // --- 2. GABEN-KONFIGURATION ---
    const gabenName = "Geisterdiener";
    const ahne = "Zerzal";
    const finalEffektName = `${gabenName} (${ahne})`; 
    const zielEffektName = "Geisterdiener";
    const radiusSchritt = 16;
    const iconBild = DSK_FW.Symbol(ahne);

    const dienerEintraege = [
        { id: "THZyemHE4b0kbmOO", name: "Heinrich der Schöne" },
        { id: "6i1IZ45Yun57SDt6", name: "Geisterdiener" }
    ];

    // --- 3. WIRKENDEN (CASTER) & QS ERMITTELN ---
    let safeTestData = typeof testData !== "undefined" ? testData : null;
    let casterActor = safeTestData?.actor || canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!casterActor) casterActor = game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined);
    if (!casterActor) return ui.notifications.warn("Kein Wirkender gefunden!");

    const qs = Number(safeTestData?.result?.QL || safeTestData?.qualityStep || casterActor.getFlag("world", "letzteGabenQS") || 1);
    await casterActor.unsetFlag("world", "letzteGabenQS");

    let casterToken = casterActor.getActiveTokens()[0] || canvas.tokens.controlled[0];
    if (!casterToken) return ui.notifications.warn("Kein Token auf der Map gefunden!");

    if (!DSK_FW.Effekt.CheckTarget(casterActor, "erwachte")) {
        return ui.notifications.warn("Wirkende Person ist nicht erwacht.");
    }

    // --- FLÜSTER-EMPFÄNGER ---
    let ownerIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
    Object.entries(casterActor.ownership || casterActor.permission || {})
        .filter(([id, lvl]) => lvl === 3 && id !== "default")
        .forEach(([id]) => ownerIds.add(id));
    const whisperEmpfaenger = Array.from(ownerIds).filter(id => game.users.get(id));

    // ============================================================
    // DIALOG-FUNKTIONEN (DialogV2 Layout)
    // ============================================================
    const askModus = async () => {
        return await foundry.applications.api.DialogV2.wait({
            window: { title: "Standort des Schädels" },
            position: { width: 420 },
            content: `
                <form>
                    <div style="font-family: 'Signika', sans-serif;">
                        ${DSK_FW.UI.Header(finalEffektName, iconBild)}
                        <div class="dskbox2" style="margin-top:10px;">
                            <p style="font-size:0.95em; line-height:1.35; text-align:center;">Wo befindet sich der Schädel?</p>
                        </div>
                    </div>
                </form>
            `,
            buttons: [
                { action: "selbst", label: "Bei mir (Folgt mir)", icon: "fas fa-user", callback: () => "selbst" },
                { action: "platzieren", label: "Auf dem Boden", icon: "fas fa-map-marker-alt", default: true, callback: () => "schablone" }
            ],
            rejectClose: false
        });
    };

    const confirmPosition = async () => {
        return await foundry.applications.api.DialogV2.wait({
            window: { title: "Schablone platzieren" },
            position: { width: 420 },
            content: `
                <form>
                    <div style="font-family: 'Signika', sans-serif;">
                        ${DSK_FW.UI.Header(finalEffektName, iconBild)}
                        <div class="dskbox2" style="margin-top:10px;">
                            <p style="font-size:0.95em; line-height:1.35;">Verschiebe die Schablone auf der Karte an den gewünschten Ort.</p>
                        </div>
                    </div>
                </form>
            `,
            buttons: [
                { action: "ok", label: "Position Bestätigen", icon: "fas fa-check", default: true, callback: () => true },
                { action: "cancel", label: "Abbrechen", icon: "fas fa-times", callback: () => false }
            ],
            rejectClose: false
        });
    };

    const askDiener = async () => {
        const optionenHtml = dienerEintraege.map(d => `<option value="${d.id}">${d.name}</option>`).join("");
        return await foundry.applications.api.DialogV2.wait({
            window: { title: "Geisterdiener wählen" },
            position: { width: 420 },
            content: `
                <form>
                    <div style="font-family: 'Signika', sans-serif;">
                        ${DSK_FW.UI.Header(finalEffektName, iconBild)}
                        <div class="dskbox2" style="margin-top:10px;">
                            <label style="font-weight: bold; font-size: 0.9em;">Welchen Diener möchtest du rufen?</label>
                            <select name="dienerId" style="width: 100%; padding: 4px; margin-top: 6px; font-family: 'Signika', sans-serif;">
                                ${optionenHtml}
                            </select>
                        </div>
                    </div>
                </form>
            `,
            buttons: [
                { 
                    action: "ok", 
                    label: "Geist Beschwören", 
                    icon: "fas fa-ghost", 
                    default: true, 
                    callback: (event) => {
                        const form = event.target.closest("form");
                        return form ? new FormData(form).get("dienerId") : null;
                    } 
                },
                { action: "cancel", label: "Abbrechen", icon: "fas fa-times", callback: () => null }
            ],
            rejectClose: false
        });
    };

    // ============================================================
    // ABLAUF START: SCHABLONE PLATZIEREN & BESTÄTIGEN
    // ============================================================
    const modus = await askModus();
    if (!modus || modus === false) return;

    let placedTemplateDoc = null;

    if (modus === "selbst") {
        const tData = {
            t: "circle", user: game.user.id, distance: radiusSchritt,
            x: casterToken.center.x, y: casterToken.center.y,
            fillColor: "#000000", fillAlpha: 0.0, lineThickness: 0, hidden: true
        };
        const created = await canvas.scene.createEmbeddedDocuments("MeasuredTemplate", [tData]);
        placedTemplateDoc = created[0];
    } else {
        const tData = {
            t: "circle", user: game.user.id, distance: radiusSchritt, 
            x: casterToken.center.x, y: casterToken.center.y, 
            fillColor: game.user.color || "#000000", fillAlpha: 0.15, lineThickness: 1, hidden: false
        };
        const created = await canvas.scene.createEmbeddedDocuments("MeasuredTemplate", [tData]);
        placedTemplateDoc = created[0];

        try { canvas.templates.activate(); } catch (e) {}

        const isConfirmed = await confirmPosition();

        try { canvas.tokens.activate(); } catch (e) {}

        if (!isConfirmed || isConfirmed === false) {
            await placedTemplateDoc.delete();
            return ui.notifications.warn("Luna sagt 🌙: Beschwörung abgebrochen.");
        }

        placedTemplateDoc = canvas.scene.templates.get(placedTemplateDoc.id);
        await placedTemplateDoc.update({ hidden: true, fillAlpha: 0.0, lineThickness: 0 });
    }

    const dienerId = await askDiener();
    if (!dienerId) {
        await placedTemplateDoc.delete(); 
        return ui.notifications.warn("Luna sagt 🌙: Beschwörung abgebrochen.");
    }

    const dienerActor = game.actors.get(dienerId);
    if (!dienerActor) {
        await placedTemplateDoc.delete();
        return ui.notifications.error("Luna sagt 🌙: Diener nicht gefunden!");
    }

    // ============================================================
    // TOKEN SPAWNEN 
    // ============================================================
    let spawnData = await dienerActor.getTokenDocument({
        x: placedTemplateDoc.x - (canvas.grid.size / 2),
        y: placedTemplateDoc.y - (canvas.grid.size / 2)
    });

    let ownership = foundry.utils.deepClone(dienerActor.ownership || {});
    ownership[game.user.id] = 3; 

    spawnData.updateSource({ 
        actorLink: false, 
        ownership: ownership,
        flags: { dsk: { spawnedByUuid: casterActor.uuid } }
    });

    const spawnedTokenDocs = await canvas.scene.createEmbeddedDocuments("Token", [spawnData]);
    const spawnedToken = spawnedTokenDocs[0];

    // ============================================================
    // EFFEKTE ANWENDEN
    // ============================================================
    await DSK_FW.Effekt.Anwenden({
        name: finalEffektName,
        ahne: ahne,
        beschreibung: `Die Seele darf sich maximal ${radiusSchritt} Schritt vom Schädel entfernen.`,
        gabeZiel: "erwachte",
        qs: qs,
        ziel: casterActor,
        flags: { dsk: { 
            casterUuid: casterActor.uuid,
            isZoneSource: true,
            templateId: placedTemplateDoc.id,
            dienerTokenId: spawnedToken.id,
            modus: modus
        }}
    });

    setTimeout(async () => {
        const currentGhost = canvas.scene.tokens.get(spawnedToken.id);
        if (currentGhost && currentGhost.actor) {
            await currentGhost.actor.createEmbeddedDocuments("ActiveEffect", [{
                name: zielEffektName,
                icon: iconBild,
                description: "Dieser Diener is materialisiert und an den Schädel gebunden.",
                flags: { dsk: { spawnedByUuid: casterActor.uuid } }
            }]);
        }
    }, 500);

    // ============================================================
    // ROBUSTER LOKALER HOOK (OHNE FEHLERBANNER BEIM LÖSCHEN)
    // ============================================================
    if (!globalThis.dskDienerHooks) globalThis.dskDienerHooks = {};
    const hookKey = casterActor.uuid + "-geisterdiener";

    if (globalThis.dskDienerHooks[hookKey]) {
        Hooks.off("deleteActiveEffect", globalThis.dskDienerHooks[hookKey].delete);
        Hooks.off("updateToken", globalThis.dskDienerHooks[hookKey].update);
    }
    globalThis.dskDienerHooks[hookKey] = {};

    globalThis.dskDienerHooks[hookKey].delete = Hooks.on("deleteActiveEffect", async (effect, options, userId) => {
        if (game.user.id !== userId) return; 

        const effName = effect.name || effect.label || "";
        if (effName === finalEffektName && effect.parent.uuid === casterActor.uuid) {

            // SICHERHEITS-CHECK: Nur löschen, wenn der Token überhaupt noch existiert (verhindert das rote Banner!)
            const tokenId = effect.flags?.dsk?.dienerTokenId || spawnedToken.id;
            const tokenToDelete = canvas.scene.tokens.get(tokenId);
            if (tokenToDelete) {
                await tokenToDelete.delete().catch(() => {});
            }

            const tokensToDelete = canvas.scene.tokens.filter(t => t.getFlag("dsk", "spawnedByUuid") === casterActor.uuid).map(t => t.id);
            if (tokensToDelete.length > 0) {
                await canvas.scene.deleteEmbeddedDocuments("Token", tokensToDelete).catch(() => {});
            }

            ChatMessage.create({
                whisper: whisperEmpfaenger,
                speaker: { alias: "System" },
                content: `
                    <div style="font-family:'Signika',sans-serif;">
                        <div class="dskbox1">
                            <p style="display:flex; gap:8px; align-items:center;">
                                <img src="${iconBild}" style="width:28px; border:none; background:transparent;">
                                <b>Wirkungsende</b>
                            </p>
                            <p style="font-weight:bold; margin-top:6px;">${finalEffektName}</p>
                        </div>
                        <div class="dskbox2" style="margin-top:10px;">
                            <p>Der materialisierte Leib der Seele verschwindet und sie kehrt in den Schädel zurück.</p>
                            <hr>
                            <p><b>Effekt beendet auf:</b></p>
                            <ul class="dsklist"><li>${effect.parent.name}</li></ul>
                        </div>
                    </div>
                `
            });

            Hooks.off("deleteActiveEffect", globalThis.dskDienerHooks[hookKey].delete);
            Hooks.off("updateToken", globalThis.dskDienerHooks[hookKey].update);
            delete globalThis.dskDienerHooks[hookKey];
        }
    });

    globalThis.dskDienerHooks[hookKey].update = Hooks.on("updateToken", async (doc, change, options, userId) => {
        if (game.user.id !== userId) return; 
        if (change.x === undefined && change.y === undefined) return;

        const caster = await fromUuid(casterActor.uuid);
        if (!caster) return;

        const effect = caster.effects.find(e => (e.name||e.label) === finalEffektName);
        if (!effect) return; 

        const flags = effect.flags?.dsk || {};
        const tmpl = canvas.scene.templates.get(flags.templateId);
        if (!tmpl) return;

        if (flags.modus === "selbst" && casterToken && doc.id === casterToken.id) {
            const newX = (change.x !== undefined ? change.x : doc.x) + (doc.width * canvas.grid.size) / 2;
            const newY = (change.y !== undefined ? change.y : doc.y) + (doc.height * canvas.grid.size) / 2;
            await tmpl.update({ x: newX, y: newY });
        }

        if (doc.id === flags.dienerTokenId) {
            const tX = change.x !== undefined ? change.x : doc.x;
            const tY = change.y !== undefined ? change.y : doc.y;
            const tCenter = { x: tX + (doc.width * canvas.grid.size)/2, y: tY + (doc.height * canvas.grid.size)/2 };
            const tmplCenter = { x: tmpl.x, y: tmpl.y };

            const dx = tmplCenter.x - tCenter.x;
            const dy = tmplCenter.y - tCenter.y;
            const distancePx = Math.hypot(dx, dy);
            const distanceSchritt = (distancePx / canvas.grid.size) * canvas.scene.grid.distance;

            if (distanceSchritt > radiusSchritt) {
                const angle = Math.atan2(dy, dx);
                const stepSize = canvas.grid.size; 
                const targetX = tX + Math.cos(angle) * stepSize;
                const targetY = tY + Math.sin(angle) * stepSize;

                await doc.update({ x: targetX, y: targetY });
                ui.notifications.warn("Luna sagt 🌙: Der Geisterdiener kann den Bereich des Schädels nicht verlassen!");
            }
        }
    });

    // ============================================================
    // FLÜSTER-NACHRICHT (START)
    // ============================================================
    const dauerText = `${qs * 5} Minuten (QS ${qs})`;
    const basisBeschreibung = `Eine durch Seelenbindung an einen Schädel gebundene Seele materialisiert sich. Sie ist physisch greifbar und verletzlich. Die Seele darf sich maximal <b>${radiusSchritt} Schritt</b> vom Schädel entfernen und wird bei Übertretung zurückgezogen.`;
    const besonderheiten = `<b>Reichweite:</b> ${radiusSchritt} Schritt`;

    let erfolgsZiele = [];
    erfolgsZiele.push(`<b>Wirkende Person:</b> ${casterActor.name}`);
    erfolgsZiele.push(`<b>Geisterdiener:</b> ${dienerActor.name}`);

    let erfolgHtml = `
        <p><span style="color:#18940F; font-weight:bold;">Erfolg</span></p>
        <ul class="dsklist" style="font-weight:normal; margin-top:4px;">
            ${erfolgsZiele.map(n => `<li>${n}</li>`).join("")}
        </ul>
    `;

    await ChatMessage.create({
        speaker: { alias: "System" },
        content: `
            <div style="font-family:'Signika',sans-serif;">
                ${DSK_FW.UI.Header(finalEffektName, iconBild)}
                ${DSK_FW.UI.Box("dskbox2", `
                    <p><b>Gabenwirkung:</b></p>
                    <p>${basisBeschreibung}<br><br>${besonderheiten}</p>
                    <hr>
                    ${erfolgHtml}
                    <hr>
                    <p style="text-align:center; font-weight:bold;">
                        Wirkungsdauer:<br>${dauerText}
                    </p>
                `)}
            </div>
        `,
        whisper: whisperEmpfaenger
    });

})();
